SourceCode.Declaration:
/// <summary>
/// Registers the <c>AAXWHSItemIdentityValue</c> data type with the warehouse app field priority
/// framework. The injected item identity control carries this data type, so the field places the
/// identity line right after the standard item description.
/// </summary>
[WHSFieldEDT(extendedTypeStr(AAXWHSItemIdentityValue))]
public class AAXWHSFieldItemIdentity extends WHSField
{
    private const WHSFieldName             Name        = "@AAXWarehouseTools:IdentityDefaultLabelValue";
    private const WHSFieldDisplayPriority  Priority    = 30;
    private const WHSFieldDisplayPriority  SubPriority = 20;
    private const WHSFieldInputMode        InputMode   = WHSFieldInputMode::Scanning;
    private const WHSFieldInputType        InputType   = WHSFieldInputType::Alpha;
}

Method.Source:
/// <summary>
/// Sets the default properties of the item identity field.
/// </summary>
protected void initValues()
{
    this.defaultName        = Name;
    this.defaultPriority    = Priority;
    this.defaultSubPriority = SubPriority;
    this.defaultInputMode   = InputMode;
    this.defaultInputType   = InputType;
}
